/* ---------- STATE ---------- */
const KEY='gpflow.v1';
let S={xp:0,streak:0,res:{},lv:0};
try{const r=JSON.parse(localStorage.getItem(KEY)||'null'); if(r&&typeof r==='object') S=Object.assign(S,r);}catch(e){}
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(S))}catch(e){}};
const LEVELS=$$('.level'); const LQ=['', 'mpp','dist','stor','expl','part','xch','pxf','load','final'];
const toastEl=$('#toast'); let tt;
function toast(t){toastEl.textContent=t;toastEl.classList.add('on');clearTimeout(tt);tt=setTimeout(()=>toastEl.classList.remove('on'),1800)}
function lvState(i){const id=LQ[i]; if(!id) return ''; const r=S.res[id]||[]; const n=r.filter(x=>x!==undefined&&x!==null).length; return n>=Q[id].length?'done':n?'part':''}
function hud(){
  
  const done=LQ.filter((id,i)=>id&&lvState(i)==='done').length;
  $('#meterFill').style.width=(done/9*100)+'%'; $('#meterTxt').textContent=done+'/9';
  $$('#map button').forEach((b,i)=>{b.className=lvState(i)});
}
/* map */
const map=$('#map');
LEVELS.forEach((s,i)=>{const b=document.createElement('button');b.innerHTML=`<span class="seg">${i===0?'—':'seg'+i}</span><span class="t">${esc(s.dataset.title)}</span><span class="st" aria-hidden="true"></span>`;
  b.setAttribute('aria-label',s.dataset.title); b.onclick=()=>go(i); map.appendChild(b)});
function go(i){
  i=Math.max(0,Math.min(LEVELS.length-1,i)); S.lv=i; save();
  LEVELS.forEach((s,k)=>s.hidden=k!==i);
  $$('#map button').forEach((b,k)=>b.setAttribute('aria-current',k===i));
  $('#pgPrev').disabled=i===0; $('#pgPrev').style.visibility=i===0?'hidden':'visible';
  $('#pgNext').hidden=i===LEVELS.length-1;
  $('#pgNext').textContent=i===0?'Начать →':'Уровень '+(i+1)+': '+LEVELS[i+1]?.dataset.short+' →';
  window.scrollTo({top:0,behavior:'instant'});
}
$('#pgPrev').onclick=()=>go(S.lv-1); $('#pgNext').onclick=()=>go(S.lv+1);
$$('[data-go]').forEach(b=>b.onclick=()=>go(+b.dataset.go));

/* ---------- QUIZ ENGINE v5 ---------- */
const quizzes={};
S.pick=S.pick||{}; S.xq=S.xq||{};
function goTheory(rid){const t0=document.getElementById(rid); if(!t0) return; let t=t0.closest('.card,.concept,.console,.cols2')||t0;
  let h=t.previousElementSibling; for(let n=0;n<3&&h;n++){if(h.matches('h3.sec'))break;h=h.previousElementSibling}
  (h&&h.matches('h3.sec')?h:t).scrollIntoView({behavior:'smooth',block:'start'}); t.classList.remove('flashy'); void t.offsetWidth; t.classList.add('flashy')}
function mountQuiz(el){
  const id=el.dataset.quiz, qs=Q[id]; S.res[id]=S.res[id]||[]; S.pick[id]=S.pick[id]||[];
  const st={i:0}; quizzes[id]=st;
  const firstOpen=()=>{const k=qs.findIndex((_,j)=>S.res[id][j]===undefined||S.res[id][j]===null);return k<0?qs.length:k};
  st.i=firstOpen();
  const optHtml=(q,k)=>q.o[k][0]==='$'?`<pre class="sql oc">${hl(q.o[k].slice(1))}</pre>`:`<span>${esc(q.o[k])}</span>`;
  function render(){
    const r=S.res[id];
    const dots=qs.map((_,j)=>`<button class="dot ${r[j]===true?'ok':r[j]===false?'no':''}${j===st.i?' cur':''}" data-j="${j}" aria-label="Вопрос ${j+1}"></button>`).join('');
    if(st.i>=qs.length){
      const ok=r.filter(x=>x===true).length;
      el.innerHTML=`<div class="quiz-h"><span>Чекпоинт пройден</span><span class="dots">${dots}</span></div><div class="quiz-b"><p class="q">${ok} из ${qs.length} с первой попытки</p><p class="src">${ok===qs.length?'Чисто. Переходи дальше.':'Нажми на красную точку, чтобы вернуться к вопросу и разобрать варианты.'}</p><div class="quiz-f"><button class="ghost" data-act="again">↺ Пройти чекпоинт заново</button>${S.lv<9?'<button class="btn" data-act="nextlv">Следующий уровень →</button>':''}</div></div>`;
      el.querySelector('[data-act=again]').onclick=()=>{S.res[id]=[];S.pick[id]=[];st.i=0;save();hud();render()};
      const nl=el.querySelector('[data-act=nextlv]'); if(nl) nl.onclick=()=>go(S.lv+1);
      bindDots(); if(id==='final') showFinal();
      return;
    }
    const q=qs[st.i], answered=r[st.i]!==undefined&&r[st.i]!==null;
    const ord=q.o.map((_,k)=>k), pr=rng(fnv(id+st.i));
    for(let k=ord.length-1;k>0;k--){const j=Math.floor(pr()*(k+1));[ord[k],ord[j]]=[ord[j],ord[k]]}
    const N=k=>ord.indexOf(k)+1;
    el.innerHTML=`<div class="quiz-h"><span>Чекпоинт · ${st.i+1}/${qs.length}</span><span class="dots">${dots}</span></div>
     <div class="quiz-b"><p class="q">${esc(q.q)}</p>${q.c?`<pre class="sql">${hl(q.c)}</pre>`:''}<div class="opts">${ord.map((k,pos)=>`<button class="opt" data-k="${k}"><span class="k">${pos+1}</span>${optHtml(q,k)}</button>`).join('')}</div>
     <div class="expl" hidden></div><div class="why" hidden></div>
     <div class="quiz-f"><span class="src hint">Выбери ответ или нажми 1–${q.o.length}</span><div class="row"><button class="ghost" data-act="retry" hidden>↺ Ответить заново</button><button class="btn" data-act="next" hidden>${st.i===qs.length-1?'Завершить':'Следующий вопрос'} ↵</button></div></div></div>`;
    const opts=[...el.querySelectorAll('.opt')], ex=el.querySelector('.expl'), why=el.querySelector('.why'), nx=el.querySelector('[data-act=next]'), rt=el.querySelector('[data-act=retry]');
    let locked=false;
    function reveal(){
      locked=true; const pick=S.pick[id][st.i], good=r[st.i];
      opts.forEach(o=>o.classList.add('done'));
      el.querySelector(`.opt[data-k="${q.a}"]`).classList.add('ok');
      if(pick!=null&&pick!==q.a) el.querySelector(`.opt[data-k="${pick}"]`).classList.add('no');
      ex.hidden=false;
      ex.innerHTML=(good?`<b>Верно.</b> ${esc(q.e)}`:`<b>Неверно.</b> ${pick!=null&&q.w?esc(q.w[pick]):''}<br><b>Правильный ответ: ${N(q.a)}.</b> ${esc(q.e)}`)
        +(q.r?` <button class="ghost reread" data-act="reread">↑ Перечитать теорию</button>`:'');
      const rr=ex.querySelector('[data-act=reread]'); if(rr) rr.onclick=()=>goTheory(q.r);
      el.querySelector('.hint').textContent='Нажми на любой вариант, чтобы узнать, почему он подходит или нет.';
      nx.hidden=false; rt.hidden=false;
    }
    opts.forEach(o=>o.onclick=()=>{
      const k=+o.dataset.k;
      if(locked){ // разбор любого варианта после ответа
        opts.forEach(x=>x.classList.toggle('peek',x===o)); why.hidden=false;
        why.innerHTML=`<b>Вариант ${N(k)}${k===q.a?' — верный':' — не подходит'}.</b> `+esc(k===q.a?q.e:(q.w&&q.w[k])||'Этот вариант не подходит.');
        return;
      }
      const ok=k===q.a; r[st.i]=ok; S.pick[id][st.i]=k;
      const key=id+':'+st.i;
      if(ok){if(!S.xq[key]){S.xq[key]=1;S.xp+=10}S.streak++;toast('Верно')}
      else{S.xq[key]=1;S.streak=0;o.classList.add('shake')}
      save();hud();reveal();nx.focus({preventScroll:true});
    });
    rt.onclick=()=>{r[st.i]=null;S.pick[id][st.i]=null;save();hud();render()};
    nx.onclick=()=>{st.i=Math.max(st.i+1,0);const nxt=qs.findIndex((_,j)=>j>=st.i&&(r[j]===undefined||r[j]===null));st.i=nxt<0?qs.length:nxt;render();el.scrollIntoView({block:'nearest',behavior:'smooth'})};
    bindDots();
    if(answered) reveal();
  }
  function bindDots(){el.querySelectorAll('.dot').forEach(d=>d.onclick=()=>{st.i=+d.dataset.j;render()})}
  st.render=render; render();
}
$$('[data-quiz]').forEach(mountQuiz);

function showFinal(){
  const r=S.res.final||[], ok=r.filter(x=>x===true).length;
  const N=Q.final.length; $('#finalRes').hidden=false; $('#finalScore').textContent=ok+'/'+N;
  $('#finalTxt').textContent=ok>=Math.ceil(N*0.8)?'Теория по Greenplum закрыта. Следующий шаг — задача 03.1 в DBeaver, шпаргалка ниже.':'Пока меньше 80%. Пройди ещё раз уровни, где в чекпоинтах остались красные точки, и вернись сюда.';
}

/* keyboard */
document.addEventListener('keydown',e=>{
  if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||e.metaKey||e.ctrlKey||e.altKey) return;
  const sec=LEVELS[S.lv];
  if(/^[1-4]$/.test(e.key)){const o=sec.querySelectorAll('.quiz .opt:not([aria-disabled])')[+e.key-1]; if(o){o.click();e.preventDefault()}}
  else if(e.key==='Enter'){const n=sec.querySelector('.quiz [data-act=next]:not([hidden])'); if(n&&document.activeElement!==n){n.click();e.preventDefault()}}
  else if(e.key==='ArrowRight') go(S.lv+1); else if(e.key==='ArrowLeft') go(S.lv-1);
});

/* ---------- L1 CLUSTER SIM ---------- */
const segWrap=$('#simSegs');
for(let i=0;i<8;i++) segWrap.insertAdjacentHTML('beforeend',`<div class="segbox" id="sg${i}"><b>seg${i}</b><span class="mono src" id="sgt${i}">idle</span><div class="fill"><i id="sgf${i}"></i></div></div>`);
let simTok=0; const wait=ms=>new Promise(r=>setTimeout(r,matchMedia('(prefers-reduced-motion: reduce)').matches?0:ms));
function simReset(){['#nClient','#nMaster','#nS3'].forEach(s=>$(s).classList.remove('hot','busy'));$('#nIc').classList.remove('hot');for(let i=0;i<8;i++){$('#sg'+i).classList.remove('busy');$('#sgf'+i).style.width='0';$('#sgt'+i).textContent='idle'}}
async function sim(kind){
  const t=++simTok, ok=()=>t===simTok, log=$('#simLog'); simReset();
  $('#nClient').classList.add('hot'); log.textContent='client → master: SQL';
  await wait(500); if(!ok())return; $('#nMaster').classList.add('hot'); log.textContent='master строит план и раздаёт его сегментам';
  if(kind==='sel'){
    await wait(600); if(!ok())return; $('#nIc').classList.add('hot');
    for(let i=0;i<8;i++){$('#sg'+i).classList.add('busy');$('#sgt'+i).textContent='count своей части';$('#sgf'+i).style.width='100%'}
    log.textContent='все 8 сегментов считают свою часть одновременно';
    await wait(1100); if(!ok())return; for(let i=0;i<8;i++){$('#sg'+i).classList.remove('busy');$('#sgt'+i).textContent='→ master'}
    log.textContent='Gather Motion 8:1: сегменты отдают 8 частичных count, мастер складывает их. Время = самый медленный сегмент.';
  }else if(kind==='ins'){
    for(let i=0;i<8;i++){
      await wait(450); if(!ok())return; $('#nMaster').classList.add('busy');
      const s=(i*5+3)%8; $('#sg'+s).classList.add('busy'); $('#sgt'+s).textContent='+1 строка'; $('#sgf'+s).style.width=Math.min(100,(+$('#sgf'+s).style.width.replace('%','')||0)+40)+'%';
      log.textContent=`строка ${i+1}/8: client → master → hash → seg${s}`;
      await wait(250); if(!ok())return; $('#sg'+s).classList.remove('busy');
    }
    log.textContent='Каждая строка прошла через мастер по очереди. На миллионах строк мастер станет узким местом.';
  }else{
    await wait(500); if(!ok())return; $('#nS3').classList.add('busy'); $('#nS3').style.opacity=1; $('#nIc').classList.add('hot');
    for(let i=0;i<8;i++){$('#sg'+i).classList.add('busy');$('#sgt'+i).textContent='PXF читает файлы';$('#sgf'+i).style.width='100%'}
    log.textContent='PXF на каждом хосте читает свою долю файлов из S3. Строки перехешируются по ключу распределения через interconnect.';
    await wait(1300); if(!ok())return; for(let i=0;i<8;i++){$('#sg'+i).classList.remove('busy');$('#sgt'+i).textContent='записано'}
    $('#nS3').classList.remove('busy'); $('#nS3').style.opacity=.55;
    log.textContent='Загрузка шла параллельно, мастер только координировал. Так работает INSERT … SELECT FROM external в 03.1.';
  }
}
$('#simSelect').onclick=()=>sim('sel'); $('#simInsert').onclick=()=>sim('ins'); $('#simPxf').onclick=()=>sim('pxf');

/* ---------- L2 DISTRIBUTION ---------- */
function rng(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
function fnv(s){let h=0x811c9dc5;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,0x01000193)}return h>>>0}
const R=rng(42), ROWS=[];
for(let i=0;i<4000;i++){const r=R();ROWS.push({ride_id:'R'+(1e9+Math.floor(R()*9e9)).toString(16)+i,rideable_type:r<.6?'classic_bike':r<.98?'electric_bike':'docked_bike',member_casual:R()<.75?'member':'casual',start_station_id:'ST'+Math.floor(600*Math.pow(R(),2.2)),started_at:'2025-09-'+String(1+Math.floor(R()*30)).padStart(2,'0')})}
const DK=[
 {k:'ride_id',l:'ride_id',v:'Ровно: уникальный ключ, хеш раскладывает строки равномерно. Хороший выбор.',good:true},
 {k:'start_station_id',l:'start_station_id',v:'Почти ровно, но популярные станции дают горбы. Подходит, если основная нагрузка — JOIN по станции.',good:true},
 {k:'started_at',l:'started_at::date',v:'Всего 30 значений: перекос заметен. Хуже другое: запрос за один день целиком выполняется на одном сегменте.',good:false},
 {k:'rideable_type',l:'rideable_type',v:'3 значения → заняты максимум 3 сегмента из 8, остальные простаивают. Плохой ключ.',good:false},
 {k:'member_casual',l:'member_casual',v:'2 значения → работают 2 сегмента из 8. Самый плохой вариант.',good:false},
 {k:'RANDOMLY',l:'RANDOMLY',v:'Ровно, но любой JOIN по этой таблице потребует пересылки строк (Redistribute или Broadcast).',good:true}];
const dk=$('#distKeys'); let curDK='rideable_type';
DK.forEach(d=>{const b=document.createElement('button');b.className='ghost mono';b.textContent=d.l;b.onclick=()=>{curDK=d.k;drawDist()};b.dataset.k=d.k;dk.appendChild(b)});
const bars=$('#distBars'); for(let i=0;i<8;i++) bars.insertAdjacentHTML('beforeend',`<div class="bar"><span id="bv${i}"></span><i id="bb${i}"></i><span>seg${i}</span></div>`);
function drawDist(){
  const c=Array(8).fill(0), d=DK.find(x=>x.k===curDK);
  ROWS.forEach((r,i)=>{c[curDK==='RANDOMLY'?Math.floor(rng(i+7)()*8):fnv(r[curDK])%8]++});
  const mx=Math.max(...c), avg=4000/8;
  c.forEach((v,i)=>{const b=$('#bb'+i);b.style.height=(v/ Math.max(mx,1)*100)+'%';b.classList.toggle('max',v===mx&&mx/avg>1.3);$('#bv'+i).textContent=v});
  $('#dMax').textContent=mx; $('#dAvg').textContent=avg; $('#dSkew').textContent=(mx/avg).toFixed(2); $('#dEmpty').textContent=c.filter(v=>!v).length;
  const k=mx/avg, kv=k<1.1?'хорошо':k<=1.25?'приемлемо':'перекос'; const v=$('#dVerdict'); v.textContent=`Коэффициент ${k.toFixed(2).replace('.',',')} — ${kv}. `+d.v; v.className='verdict '+(d.good?'good':'bad');
  $('#dSql').innerHTML=hl('CREATE TABLE stg.citibike_trips (…)\nDISTRIBUTED '+(curDK==='RANDOMLY'?'RANDOMLY;':'BY ('+curDK+');'));
  $$('#distKeys button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.k===curDK));
}
drawDist();

/* ---------- L3 STORAGE ---------- */
const COLS=['ride_id','type','start','end','st_from','st_to','coords','member'];
const NEED={avg:[2,3],grp:[7],all:[0,1,2,3,4,5,6,7]};
