function drawVal(){
  const ao=$('#vAo').value==='true', or=$('#vOr').value, ct=$('#vCt').value;
  const opts=['appendoptimized = '+ao]; if(or) opts.push('orientation     = '+or); if(ct) opts.push('compresstype    = '+ct);
  $('#vDdl').innerHTML=hl('CREATE TABLE stg.t (…)\nWITH (\n    '+opts.join(',\n    ')+'\n)\nDISTRIBUTED BY (ride_id);');
  let ok=true,msg;
  if(!ao&&(or==='column'||ct)){ok=false;msg='Ошибка. Heap — это шаг 1 и конец выбора: '+(or==='column'?'колоночная ориентация':'сжатие')+' есть только у append-optimized таблиц. Поставь appendoptimized = true.'}
  else if(ct==='rle_type'&&or!=='column'){ok=false;msg='Ошибка. rle_type сжимает серии одинаковых значений подряд, а они есть только в колоночном хранении. Нужно orientation = column.'}
  else if(!ao) msg='Создастся обычная heap-таблица без сжатия. Подходит для маленьких таблиц с частыми UPDATE.';
  else msg='Создастся. AO, '+(or==='column'?'колоночное':'строковое')+' хранение'+(or?'':' (row по умолчанию)')+(ct?', сжатие '+ct:', без сжатия')+'.';
  const v=$('#vRes'); v.className='verdict '+(ok?'good':'bad'); v.textContent=msg;
  if(!ok){$('#vBars').innerHTML='<p class="src">Таблица не создастся, сравнивать нечего.</p>';return}
  const col=or==='column', size=!ao?100:ct?(col?(ct==='rle_type'?30:28):35):(col?92:95), read=col?Math.round(size*3/13):size;
  $('#vBars').innerHTML=`<div class="vbar"><span>Место на диске</span><div class="tr"><i style="width:${size}%"></i><span>≈ ${size} ГБ</span></div></div>
    <div class="vbar read"><span>Прочитает SELECT по 3 колонкам</span><div class="tr"><i style="width:${read}%"></i><span>≈ ${read} ГБ${col?' (только 3 файла колонок)':' (строки целиком)'}</span></div></div>`;
}
