const STNS=[{seg:1,k:0,fid:'n0'},{seg:3,k:1,fid:'n1'},{seg:4,k:2,fid:'n2'},{seg:6,k:3,fid:'n3'}];
const RSEG=[1,3,4,6];
const chip=c=>`<i class="mchip${c.st?' st':' sq'}${c.from?' cp':''}" data-fid="${c.fid}"${c.from?` data-from="${c.from}"`:''} style="--c:${KC(c.k)}">${KL[c.k]}</i>`;
