function moGroup(rows,f){const a=[];rows.forEach(r=>{(a[f(r)]=a[f(r)]||[]).push(r)});return a}
let moTok=0;
async function motion(kind){
  const t=++moTok; $$('[data-mo]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.mo===kind));
  const data=kind==='bcast'?STNS.map(r=>({...r,st:true})):TRIPS;
  moShow(moGroup(data,r=>r.seg),[]); $('#moM').classList.remove('hot'); $('#moCnt').textContent='';
  $('#moTxt').textContent=kind==='bcast'?'До: маленькая таблица stations, по одной строке на 4 сегментах.':'До: поездки лежат по сегментам по ride_id, цвета (station_id) перемешаны.';
  await wait(900); if(t!==moTok) return;
  const box=$('#moCard');
  if(kind==='gather'){flipRender(box,()=>moShow([],TRIPS));$('#moM').classList.add('hot');$('#moCnt').textContent='по сети: 16 строк, 8 отправителей → 1 получатель';
    $('#moTxt').textContent='Gather 8:1: все сегменты отправили свои строки мастеру. Так в конце запроса результат собирается для клиента. Поэтому на сегментах стараются заранее всё свернуть, чтобы на мастер ехало поменьше.'}
  if(kind==='redis'){const moved=TRIPS.filter(r=>RSEG[r.k]!==r.seg).length;flipRender(box,()=>moShow(moGroup(TRIPS,r=>RSEG[r.k]),[]));$('#moCnt').textContent=`по сети: ${moved} строк из 16, 8 → 8`;
    $('#moTxt').textContent='Redistribute 8:8: каждая строка уехала на сегмент hash(station_id). Все A вместе, все B вместе. Строк столько же, они просто перетасованы. Теперь GROUP BY или JOIN по station_id выполнится локально.'}
  if(kind==='bcast'){const a=[];for(let i=0;i<8;i++) a[i]=STNS.map(r=>r.seg===i?{...r,st:true}:{...r,st:true,fid:r.fid+'c'+i,from:r.fid});flipRender(box,()=>moShow(a,[]),1100);$('#moCnt').textContent='по сети: 28 строк (4 строки × 7 сегментов)';
    $('#moTxt').textContent='Broadcast 8:8: каждый сегмент отправил свои строки всем. У каждого полная копия stations (бледные — полученные копии). 4 строки превратились в 32. Для маленькой таблицы это дёшево, для большой — самый дорогой вариант.'}
}
