/* ---------- ABBREVIATIONS: list + first-use tooltips ---------- */
const ABBR={MPP:'massively parallel processing — массово-параллельная обработка',OLTP:'online transaction processing — много коротких транзакций: создать заказ, обновить статус',OLAP:'online analytical processing — тяжёлые аналитические запросы по большим объёмам',
 ACID:'atomicity, consistency, isolation, durability — атомарность, согласованность, изолированность, долговечность транзакций',SQL:'structured query language — язык запросов к базе',DDL:'data definition language — команды создания и изменения структуры: CREATE, ALTER, DROP',
 AO:'append-optimized — тип таблиц Greenplum для загрузки большими пачками',RLE:'run-length encoding — кодирование повторов',PXF:'Platform Extension Framework — сервис Greenplum для параллельного чтения внешних данных',
 FDW:'Foreign Data Wrapper — механизм PostgreSQL для доступа к внешним данным',JDBC:'Java Database Connectivity — стандартный драйвер подключения к базе',ODBC:'Open Database Connectivity — стандартный драйвер подключения к базе',
 GPSS:'Greenplum Streaming Server — сервер потоковой загрузки',HDFS:'Hadoop Distributed File System — распределённая файловая система Hadoop',S3:'Simple Storage Service — объектное хранилище: Amazon S3 и совместимые (Yandex Object Storage, MinIO)',
 ETL:'extract, transform, load — извлечь, преобразовать, загрузить',DAG:'directed acyclic graph — граф задач в Airflow',GPORCA:'оптимизатор запросов Greenplum по умолчанию',ORCA:'оптимизатор запросов Greenplum по умолчанию (GPORCA)',
 CSV:'comma-separated values — текстовая таблица с разделителем-запятой',TSV:'tab-separated values — текстовая таблица с разделителем-табуляцией',JSON:'JavaScript Object Notation — текстовый формат данных',YAML:'текстовый формат конфигурационных файлов',DWH:'data warehouse — хранилище данных',HTTP:'протокол передачи веб-запросов'};
$('#abbrList').innerHTML=Object.entries(ABBR).filter(([k])=>k!=='ORCA').map(([k,v])=>`<div><b>${k}</b><span>${esc(v)}</span></div>`).join('');
(function(){
  const SKIP=/^(PRE|CODE|A|BUTTON|SELECT|OPTION|SCRIPT|STYLE|TEXTAREA|H1|H2|B|svg|text)$/i;
  LEVELS.forEach(sec=>{
    if(sec.dataset.lv==='1'&&false) return;
    const seen=new Set();
    const walker=document.createTreeWalker(sec,NodeFilter.SHOW_TEXT,{acceptNode(n){for(let p=n.parentNode;p&&p!==sec;p=p.parentNode){if(SKIP.test(p.nodeName)||p.classList&&(p.classList.contains('term')||p.classList.contains('quiz')||p.classList.contains('task')||p.classList.contains('abbrs')))return NodeFilter.FILTER_REJECT}return NodeFilter.FILTER_ACCEPT}});
    const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
    const keys=Object.keys(ABBR).sort((a,b)=>b.length-a.length);
    nodes.forEach(node=>{
      let t=node.nodeValue, m=null, key=null;
      for(const k of keys){if(seen.has(k))continue;const re=new RegExp('(^|[^A-Za-zА-Яа-яЁё0-9_])('+k+')(?![A-Za-z0-9_])');const mm=re.exec(t);if(mm&&(!m||mm.index<m.index)){m=mm;key=k}}
      if(!m) return; seen.add(key); if(key==='GPORCA') seen.add('ORCA');
      const start=m.index+m[1].length, span=document.createElement('span');
      span.className='term'; span.tabIndex=0; span.dataset.a=key; span.textContent=key;
      const after=node.splitText(start); after.nodeValue=after.nodeValue.slice(key.length); node.parentNode.insertBefore(span,after);
    });
  });
})();
function bindTerms(root){root.querySelectorAll('.term').forEach(t=>{if(t._b)return;t._b=1;const show=()=>{tip.textContent=t.dataset.a?`${t.dataset.a} — ${ABBR[t.dataset.a]}`:(GLOSS[t.dataset.g]||'');tip.hidden=false;const r=t.getBoundingClientRect();
  tip.style.left=Math.max(8,Math.min(window.scrollX+r.left,window.scrollX+document.documentElement.clientWidth-tip.offsetWidth-8))+'px';tip.style.top=(window.scrollY+r.bottom+6)+'px'};
  t.addEventListener('mouseenter',show);t.addEventListener('focus',show);t.addEventListener('click',show);t.addEventListener('mouseleave',()=>tip.hidden=true);t.addEventListener('blur',()=>tip.hidden=true)})}
bindTerms(document);

