function hlOut(s){
  const lines=s.split('\n'); let hdDone=false;
  return lines.map((ln,i)=>{
    const e=esc(ln);
    if(/^\s*-[-+]+\s*$/.test(ln)) return `<span class="cmt">${e}</span>`;
    if(/^\(\d+ rows?\)$/.test(ln.trim())) return `<span class="cmt">${e}</span>`;
    if(/^(NOTICE|HINT|ERROR|WARNING):/.test(ln)) return e.replace(/^(NOTICE|HINT|ERROR|WARNING):/,m=>`<span class="${m.startsWith('ERROR')?'err':'kw'}">${m}</span>`);
    if(!hdDone&&lines[i+1]&&/^\s*-[-+]+\s*$/.test(lines[i+1])){hdDone=true;return `<span class="hd">${e}</span>`}
    return e.replace(/('[^']*')|(\b\d[\d.]*\b)/g,(m,str,n)=>str?`<span class="dv">${str}</span>`:`<span class="num">${n}</span>`);
  }).join('\n');
}
